import com.sun.net.httpserver.HttpExchange;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.PBEKeySpec;

/** Local application accounts; only a SHA-256 digest of the session token is stored. */
public class Auth {
  private static final SecureRandom RANDOM=new SecureRandom();
  private static boolean initialized=false;
  private static final Map<String,ArrayDeque<Long>> attempts=new HashMap<>();
  private static final String USERS="dbo.LichTruongUsers", STATES="dbo.LichTruongUserState";
  static synchronized void initialize() throws Exception {
    if(initialized)return;
    Main.SqlStore.query("SET NOCOUNT ON; IF OBJECT_ID(N'"+USERS+"',N'U') IS NULL CREATE TABLE "+USERS+" (id int IDENTITY(1,1) PRIMARY KEY, username varchar(40) NOT NULL UNIQUE, salt varchar(32) NOT NULL, passhash varchar(64) NOT NULL, sessionhash varchar(64) NULL, expires datetime2 NULL); IF OBJECT_ID(N'"+STATES+"',N'U') IS NULL CREATE TABLE "+STATES+" (user_id int PRIMARY KEY REFERENCES "+USERS+"(id), data nvarchar(max) NOT NULL); ");
    initialized=true;
  }
  static boolean originOK(HttpExchange e){String host=e.getRequestHeaders().getFirst("Host"),origin=e.getRequestHeaders().getFirst("Origin");return ("localhost:3000".equalsIgnoreCase(host)||"127.0.0.1:3000".equals(host))&&(origin==null||origin.equals("http://localhost:3000")||origin.equals("http://127.0.0.1:3000"));}
  static String token(HttpExchange e){String cookies=e.getRequestHeaders().getFirst("Cookie");if(cookies==null)return "";for(String c:cookies.split(";")){String[] p=c.trim().split("=",2);if(p.length==2&&p[0].equals("lt_session")&&p[1].matches("[0-9a-f]{64}"))return p[1];}return "";}
  static String digest(String token)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(token.getBytes(StandardCharsets.US_ASCII)));}
  static String randomHex(int n){byte[] b=new byte[n];RANDOM.nextBytes(b);return HexFormat.of().formatHex(b);}
  static String hashPassword(String password,String salt)throws Exception{PBEKeySpec spec=new PBEKeySpec(password.toCharArray(),HexFormat.of().parseHex(salt),210000,256);try{return HexFormat.of().formatHex(SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded());}finally{spec.clearPassword();}}
  static synchronized boolean allowed(String key){long now=System.currentTimeMillis();ArrayDeque<Long> q=attempts.computeIfAbsent(key,k->new ArrayDeque<>());while(!q.isEmpty()&&q.peek()<now-60000)q.remove();if(q.size()>=10)return false;q.add(now);return true;}
  static String lookup(String token)throws Exception{if(token.isEmpty())return "";initialize();return Main.SqlStore.query("SET NOCOUNT ON; SELECT CONVERT(varchar(12),id)+'|'+username FROM "+USERS+" WHERE sessionhash='"+digest(token)+"' AND expires>SYSUTCDATETIME();");}
  static Map<String,Object> bootstrap(String token)throws Exception{if(token.isEmpty())return null;initialize();String out=Main.SqlStore.query("SET NOCOUNT ON; SELECT CONVERT(varchar(12),u.id)+'|'+u.username+'|'+CASE WHEN s.data IS NULL THEN 'EMPTY' ELSE CAST(N'' AS XML).value('xs:base64Binary(sql:column(\"s.data\"))','varchar(max)') END FROM "+USERS+" u LEFT JOIN (SELECT user_id,CONVERT(varbinary(max),data) data FROM "+STATES+") s ON s.user_id=u.id WHERE u.sessionhash='"+digest(token)+"' AND u.expires>SYSUTCDATETIME();");if(out.isEmpty())return null;String[] p=out.split("\\|",3);if(p.length!=3)throw new IOException("Không đọc được dữ liệu tài khoản.");Object data=p[2].equals("EMPTY")?null:new Main.Json(Main.cleanState(new String(Base64.getDecoder().decode(p[2].replaceAll("\\s+","")),StandardCharsets.UTF_16LE))).parse();Map<String,Object> result=new LinkedHashMap<>();result.put("id",Integer.parseInt(p[0]));result.put("username",p[1]);result.put("state",data);return result;}
  static boolean authorize(HttpExchange e)throws Exception{if(!originOK(e)){Main.reply(e,403,"application/json","{\"error\":\"Yêu cầu không hợp lệ.\"}");return false;}String info=lookup(token(e)),expected=e.getRequestHeaders().getFirst("X-LT-User");if(info.isEmpty()||expected==null||!info.split("\\|",2)[0].equals(expected)){Main.reply(e,401,"application/json","{\"error\":\"Phiên đăng nhập đã hết hiệu lực. Vui lòng đăng nhập lại.\"}");return false;}return true;}
  static String loadState(String token)throws Exception{String hash=digest(token);String out=Main.SqlStore.query("SET NOCOUNT ON; SELECT CASE WHEN s.data IS NULL THEN 'EMPTY' ELSE CAST(N'' AS XML).value('xs:base64Binary(sql:column(\"s.data\"))','varchar(max)') END FROM "+USERS+" u LEFT JOIN (SELECT user_id,CONVERT(varbinary(max),data) data FROM "+STATES+") s ON s.user_id=u.id WHERE u.sessionhash='"+hash+"' AND u.expires>SYSUTCDATETIME();");if(out.isEmpty())return null;if(out.equals("EMPTY"))return "null";return new String(Base64.getDecoder().decode(out.replaceAll("\\s+","")),StandardCharsets.UTF_16LE);}
  static boolean saveState(String token,String data)throws Exception{String hex=HexFormat.of().formatHex(data.getBytes(StandardCharsets.UTF_16LE)),hash=digest(token);String out=Main.SqlStore.query("SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRAN; DECLARE @uid int; SELECT @uid=id FROM "+USERS+" WITH (UPDLOCK,HOLDLOCK) WHERE sessionhash='"+hash+"' AND expires>SYSUTCDATETIME(); IF @uid IS NULL BEGIN ROLLBACK; SELECT 'NO'; RETURN; END; DECLARE @data nvarchar(max)=CONVERT(nvarchar(max),0x"+hex+"); UPDATE "+STATES+" SET data=@data WHERE user_id=@uid; IF @@ROWCOUNT=0 INSERT INTO "+STATES+"(user_id,data) VALUES(@uid,@data); COMMIT; SELECT 'OK';");return out.equals("OK");}
  static void cookie(HttpExchange e,String token){e.getResponseHeaders().add("Set-Cookie","lt_session="+token+"; Path=/; HttpOnly; SameSite=Strict; Max-Age="+(token.isEmpty()?"0":"2592000"));e.getResponseHeaders().set("Cache-Control","no-store");}
  static String body(HttpExchange e)throws IOException{byte[] b=e.getRequestBody().readNBytes(8193);if(b.length>8192)throw new IllegalArgumentException("Dữ liệu quá lớn.");return new String(b,StandardCharsets.UTF_8);}
  static void handle(HttpExchange e){try{
    if(!originOK(e)){Main.reply(e,403,"application/json","{\"error\":\"Yêu cầu không hợp lệ.\"}");return;}
    String path=e.getRequestURI().getPath(),method=e.getRequestMethod();e.getResponseHeaders().set("Cache-Control","no-store");
    if(path.equals("/api/auth/bootstrap")&&method.equals("GET")){Map<String,Object> data=bootstrap(token(e));if(data==null){Main.reply(e,401,"application/json","{\"error\":\"Chưa đăng nhập.\"}");return;}Main.reply(e,200,"application/json",Main.Json.stringify(data));return;}
    if(path.equals("/api/auth/me")&&method.equals("GET")){String info=lookup(token(e));if(info.isEmpty()){Main.reply(e,401,"application/json","{\"error\":\"Chưa đăng nhập.\"}");return;}String[] p=info.split("\\|",2);Main.reply(e,200,"application/json",Main.Json.stringify(Map.of("id",Integer.parseInt(p[0]),"username",p[1])));return;}
    if(path.equals("/api/auth/logout")&&method.equals("POST")){String t=token(e);if(!t.isEmpty()){initialize();Main.SqlStore.query("SET NOCOUNT ON; UPDATE "+USERS+" SET sessionhash=NULL,expires=NULL WHERE sessionhash='"+digest(t)+"';");}cookie(e,"");Main.reply(e,200,"application/json","{\"ok\":true}");return;}
    boolean register=path.equals("/api/auth/register"),login=path.equals("/api/auth/login");if(!method.equals("POST")||(!register&&!login)){Main.reply(e,404,"application/json","{}");return;}
    if(!allowed(e.getRemoteAddress().getAddress().getHostAddress())){Main.reply(e,429,"application/json","{\"error\":\"Bạn thao tác quá nhiều lần. Hãy thử lại sau một phút.\"}");return;}
    Object raw=new Main.Json(body(e)).parse();if(!(raw instanceof Map<?,?> m))throw new IllegalArgumentException("Dữ liệu không hợp lệ.");String username=Objects.toString(m.get("username"),"").trim().toLowerCase(Locale.ROOT),password=Objects.toString(m.get("password"),"");
    if(!username.matches("[a-z0-9._-]{3,40}"))throw new IllegalArgumentException("Tên đăng nhập cần 3–40 ký tự, chỉ gồm chữ không dấu, số, dấu chấm, gạch dưới hoặc gạch ngang.");if(password.length()<10||password.length()>128)throw new IllegalArgumentException("Mật khẩu cần từ 10 đến 128 ký tự.");
    initialize();String newToken=randomHex(32),session=digest(newToken),id;
    if(register){String salt=randomHex(16),hash=hashPassword(password,salt);String sql="SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRAN; DECLARE @first bit=CASE WHEN EXISTS(SELECT 1 FROM "+USERS+" WITH (UPDLOCK,HOLDLOCK)) THEN 0 ELSE 1 END; IF EXISTS(SELECT 1 FROM "+USERS+" WHERE username='"+username+"') BEGIN ROLLBACK; SELECT 'EXISTS'; RETURN; END; INSERT INTO "+USERS+"(username,salt,passhash,sessionhash,expires) VALUES('"+username+"','"+salt+"','"+hash+"','"+session+"',DATEADD(day,30,SYSUTCDATETIME())); DECLARE @uid int=SCOPE_IDENTITY(); IF @first=1 AND OBJECT_ID(N'dbo.LichTruongState',N'U') IS NOT NULL EXEC sp_executesql N'INSERT INTO dbo.LichTruongUserState(user_id,data) SELECT @id,data FROM dbo.LichTruongState WHERE id=1',N'@id int',@id=@uid; COMMIT; SELECT CONVERT(varchar(12),@uid);";id=Main.SqlStore.query(sql);if(id.equals("EXISTS")){Main.reply(e,409,"application/json","{\"error\":\"Tên đăng nhập đã được sử dụng.\"}");return;}}
    else {String found=Main.SqlStore.query("SET NOCOUNT ON; SELECT CONVERT(varchar(12),id)+'|'+salt+'|'+passhash FROM "+USERS+" WHERE username='"+username+"';");String[] p=found.split("\\|");if(p.length!=3||!MessageDigest.isEqual(hashPassword(password,p.length==3?p[1]:"00000000000000000000000000000000").getBytes(StandardCharsets.US_ASCII),(p.length==3?p[2]:"invalid").getBytes(StandardCharsets.US_ASCII))){Main.reply(e,401,"application/json","{\"error\":\"Tên đăng nhập hoặc mật khẩu chưa đúng.\"}");return;}id=p[0];Main.SqlStore.query("SET NOCOUNT ON; UPDATE "+USERS+" SET sessionhash='"+session+"',expires=DATEADD(day,30,SYSUTCDATETIME()) WHERE id="+Integer.parseInt(id)+";");}
    cookie(e,newToken);Main.reply(e,200,"application/json",Main.Json.stringify(Map.of("id",Integer.parseInt(id),"username",username)));
  }catch(IllegalArgumentException ex){try{Main.reply(e,400,"application/json",Main.Json.stringify(Map.of("error",Objects.toString(ex.getMessage(),"Dữ liệu không hợp lệ."))));}catch(IOException ignored){}}catch(Exception ex){try{Main.reply(e,503,"application/json",Main.Json.stringify(Map.of("error","Không thể xử lý yêu cầu. Hãy kiểm tra kết nối và quyền SQL Server.")));}catch(IOException ignored){}}}
}
